--   ns.ACH_SPOTS[id]  = { t = text, at = { {uiMapID, x, y}, ... } } when the whole achievement happens in one place
--   ns.CRIT_NOTES[id] = { [criterion name] = { t = text, at = { {uiMapID, x, y} } } }

