    [41042] = "The Siren Isle weekly quests depend on that week's invasion (vrykul, naga or pirates), so it takes three weeks to see them all.",
    [41043] = "Hand in Flame-Blessed Iron at the command map in the middle of Siren Isle, once for each excavation. If one is full, change shard or come back later.",
